beginning.embedded_functions:
void on_load(){
    srand(time(NULL)); 
}

//customized function to
// generate randomly number from 2 -> 10
int em_my_random(){
    int max = 10, min = 2;
    return (rand() % (max-min) + min);
}
//override the random function
#define random em_my_random

static void em_modify_dicom_version(
  const rule_info_t *rule, int verdict, uint64_t timestamp, 
  uint64_t counter, const mmt_array_t * const trace ){
    int new_val = random();
    int is_string = 0;
    // replace_dicom_attribute(PROTO_DICOM, DICOM_PROTO_VERSION, &new_val, is_string); 
    replace_dicom_attribute(701, 3, &new_val, is_string);
    forward_packet();
}
